//! Atom feed, in the same format as the one generated by jekyll-feed.
//!
//! IMPORTANT: feed readers identify entries by their `<id>`, and may flag an
//! entry as updated when its `<updated>` changes. To not notify subscribers
//! again about old posts, these must stay the same as the ones generated by
//! jekyll-feed: the `<id>` is the post URL without `.html`, and `<updated>` is
//! the publication date (jekyll-feed ignored `modified_date`).

use crate::build::RenderedPost;
use crate::config::Config;

fn xml_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            _ => out.push(c),
        }
    }
    out
}

/// `posts` must be sorted newest first.
pub fn atom(config: &Config, posts: &[RenderedPost]) -> String {
    let url = &config.url;
    let posts = &posts[..posts.len().min(config.feed_limit)];
    let updated = posts
        .iter()
        .flat_map(|p| [Some(p.post.date), p.post.modified_date])
        .flatten()
        .max()
        .map(|d| d.to_rfc3339())
        .unwrap_or_default();

    let mut out = String::new();
    out.push_str(
        r#"<?xml version="1.0" encoding="utf-8"?><feed xmlns="http://www.w3.org/2005/Atom" >"#,
    );
    out.push_str(&format!(
        r#"<link href="{url}/feed.xml" rel="self" type="application/atom+xml" /><link href="{url}/" rel="alternate" type="text/html" /><updated>{updated}</updated><id>{url}/feed.xml</id><title type="html">{}</title><subtitle>{}</subtitle>"#,
        xml_escape(&config.title),
        xml_escape(&config.description),
    ));
    for p in posts {
        let post = &p.post;
        let link = format!("{url}{}", post.url);
        let id = link.strip_suffix(".html").unwrap_or(&link);
        let title = xml_escape(&post.title);
        let published = post.date.to_rfc3339();
        out.push_str(&format!(
            r#"<entry><title type="html">{title}</title><link href="{link}" rel="alternate" type="text/html" title="{title}" /><published>{published}</published><updated>{published}</updated><id>{id}</id><content type="html" xml:base="{link}">{}</content><author><name></name></author><summary type="html">{}</summary></entry>"#,
            xml_escape(p.html.trim()),
            xml_escape(&p.excerpt),
        ));
    }
    out.push_str("</feed>");
    out
}
